<script setup lang="ts">
import { ref, computed, onMounted } from 'vue'
import { useRoute } from 'vue-router'
import { useAuth } from '../stores/auth'
import { api } from '../api/client'
import { money } from '../utils/format'
import RecordTable from '../components/RecordTable.vue'
import AgentTeamReport from '../components/AgentTeamReport.vue'
import AgentCodePurchase from '../components/AgentCodePurchase.vue'
const route=useRoute(), auth=useAuth(), section=computed(()=>String(route.params.section)),loading=ref(false),rows=ref<any[]>([]),overview=ref<any>({}),page=ref(1),total=ref(0)
const titles:Record<string,string>={overview:'代理概览',prices:'代理商品价格',codes:'卡密库存',orders:'代理订单',bills:'代理账单',team:'名下代理'}
const ledgerNote=(value:any)=>{if(!value)return '—';try{const parsed=JSON.parse(value);const contract=parsed.contract;if(parsed.batch_id&&contract&&Number.isInteger(contract.unit_price))return `卡密采购 · 商品 #${contract.product_id} · ${contract.quantity} 张 · ${money(contract.unit_price)}/张 · 批次 ${parsed.batch_id}`;return value}catch{return value}}
const columns=computed(()=>section.value==='prices'?[{key:'name',label:'商品名称',width:180},{key:'price',label:'零售价',type:'money'},{key:'effective_price',label:'专属采购价',type:'money'},{key:'price_source',label:'定价来源',type:'status'},{key:'can_purchase',label:'采购权限',type:'boolean'},{key:'restriction',label:'说明',width:200},{key:'stock',label:'库存'}]:section.value==='codes'?[{key:'id',label:'编号'},{key:'suffix',label:'卡密尾号'},{key:'batch_id',label:'批次',width:180},{key:'status',label:'状态',type:'status'},{key:'expires_at',label:'到期时间',type:'date',width:180}]:section.value==='orders'?[{key:'id',label:'订单编号',width:230},{key:'product_name',label:'商品'},{key:'amount',label:'采购额',type:'money'},{key:'fulfillment_status',label:'履约状态',type:'status'},{key:'created_at',label:'时间',type:'date',width:180}]:[{key:'id',label:'流水号'},{key:'kind',label:'类型',type:'status'},{key:'amount',label:'变动金额',type:'money'},{key:'balance_after',label:'余额',type:'money'},{key:'created_at',label:'时间',type:'date',width:180}])
const displayColumns=computed(()=>section.value==='bills' ? [...columns.value.slice(0,4),{key:'note_display',label:'交易说明',width:360},...columns.value.slice(4)] : columns.value)
async function load(){loading.value=true;try{if(section.value==='team')return;else if(section.value==='overview')overview.value=(await api.get('/agent/overview')).data;else{const endpoint={prices:'/agent/prices',codes:'/agent/codes',orders:'/me/orders',bills:'/me/transactions'}[section.value]||'/agent/prices';const{data}=await api.get(endpoint,{params:{page:page.value}});const items=Array.isArray(data)?data:data.items;rows.value=section.value==='bills'?items.map((item:any)=>({...item,note_display:ledgerNote(item.note)})):items;total.value=data.total||0}}finally{loading.value=false}}
onMounted(load)
</script>
<template><div class="section-heading"><div><p class="eyebrow">PARTNER WORKSPACE</p><h1>{{titles[section]}}</h1></div><div><AgentCodePurchase v-if="section==='codes' && auth.user?.role==='agent'" @purchased="load" /><el-button v-if="section!=='team'" @click="load">刷新数据</el-button></div></div><AgentTeamReport v-if="section==='team'" /><template v-else-if="section==='overview'"><div class="stats-grid"><div class="stat-card"><span>代理等级</span><strong>{{overview.level||'—'}}</strong><small>可配置等级 · 专属采购价格</small></div><div class="stat-card"><span>采购订单</span><strong>{{overview.order_count||0}}</strong><small>累计采购金额 {{money(overview.purchase_amount)}}</small></div><div class="stat-card"><span>持有卡密</span><strong>{{overview.code_count||0}}</strong><small>卡密采购累计 {{money(overview.code_purchase_amount)}}</small></div><div class="stat-card"><span>钱包余额</span><strong>{{money(overview.wallet?.balance)}}</strong><small>余额及账单全程可查</small></div></div><el-alert v-if="overview.level_active===false" title="当前代理等级已停用，暂停新采购，已有订单和卡密仍可查询。" type="warning" :closable="false" class="spaced"/><section class="panel"><h3>让每一笔业务更清晰</h3><p class="muted">在商品中心使用代理专属价采购。可在卡密库存按专属采购价扣余额发卡，也可接收管理员分配的卡密。完整卡密仅生成时交付。</p><router-link to="/products" class="solid-link">查看商品 →</router-link></section><el-alert title="当前阶段统计平台采购数据；线下转售价、利润、佣金及多级代理结算不在第一阶段计算。" :closable="false" type="info" /></template><section v-else class="panel table-panel"><el-alert v-if="section==='codes'" title="完整卡密不会保存在数据库中；此处仅展示尾号。过期的未使用卡密不可兑换。" :closable="false" class="spaced" /><RecordTable :rows="rows" :columns="displayColumns" :loading="loading" /><el-pagination v-if="total" v-model:current-page="page" :total="total" :page-size="20" layout="total,prev,pager,next" @current-change="load" /></section></template>
